// game/Libraries/Source/WWVegas/WW3D2/agg_def.cpp.
// Target RVA0x001A3190 262B: aggregate vtable VA0x00BD6C70 slot0x30.
// Target establishes RenderObj slots0x18/0x80/0x84/0x88/0xC8 and
